    counts = {v: sum(row.count(v) for row in grid) for v in set(x for row in grid for x in row)}
    background = max(counts, key=counts.get)
    # Continue every diagonal run of matching color, stopping at any colored obstacle.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                er, ec = r, c
                length = 1
                while 0 <= er + dr < h and 0 <= ec + dc < w and grid[er + dr][ec + dc] == color:
                    er, ec = er + dr, ec + dc
                    length += 1
                if length < 2:
                    continue
                nr, nc = er + dr, ec + dc
                while 0 <= nr < h and 0 <= nc < w and out[nr][nc] == background:
                    out[nr][nc] = color
                    nr, nc = nr + dr, nc + dc
    return out

